    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_xingce_data_calc_fraction_compare'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '分数比较', 'kp-xingce-data-calc-fraction-compare', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "分数比较"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "不算出具体商的情况下，直接比较多个分数（如比重、基期量）大小的方法。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "常出现于“下列主体中，某某比重最高/最低的是？”、“按基期量从大到小排序”等题目中。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心公式与法则"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "1. 大大则大（秒杀档）：", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 若分子 A > C 且 分母 B < D，必然 A/B > C/D。"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "2. 差分法（精细战）：", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 构造差分数进行逼近比对。"}]}, {"type": "katexBlock", "attrs": {"content": "差分数 = \\frac{大分子 - 小分子}{大分母 - 小分母}"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[列出需要比较的两个分数] --> B{分子分母是否一反一正?}\nB -- 是(分子大分母小) --> C[使用'大大则大'秒杀]\nB -- 否(同大同小) --> D[观察横向/纵向倍数]\nD -- 倍数明显 --> E[涨幅大的一方大]\nD -- 差距极小胶着 --> F[使用差分法]\nF --> G[用差分数代替大分数与小分数相比]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 比较 345/789 和 368/832 的大小。"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "识别：同大同小，368>345，832>789。无法直接秒杀。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "构造差分数：分子之差 = 368 - 345 = 23；分母之差 = 832 - 789 = 43。差分数为 23/43。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "比较差分数与小分数：比较 23/43 和 345/789。23/43 明显大于 50%，而 345/789 明显不到 50% (789的一半是394)。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "结论：差分数 > 小分数。因此大分数 368/832 更大！"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "盲目列竖式硬算：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "分数比较的核心要义就是“比”，而不是“算”。考场上谁去把四个分数全部算出小数点后三位再排大小，谁就中了命题人的圈套，必将耗尽时间。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "做排序题时，强迫自己只用眼睛看“分子分母谁涨得快”，坚决不动笔列除法竖式，直到练就一眼看穿倍数关系的直觉。"}]}]}$$ AS jsonb), NULL, '分数比较的核心考点与实战推导。', category_node.id, CAST('["资料分析", "分数比较"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_data_calc_fraction_compare", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
